import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Zähler-Reset und Überlauf","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/05.hintergrund/02.zaehler-reset.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/hintergrund/zaehler-reset.md","filePath":"de/adapter/sourceanalytix/hintergrund/zaehler-reset.md","lastUpdated":null}'),d={name:"de/adapter/sourceanalytix/hintergrund/zaehler-reset.md"};function i(s,e,l,h,u,o){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="zahler-reset-und-uberlauf" tabindex="-1">Zähler-Reset und Überlauf <a class="header-anchor" href="#zahler-reset-und-uberlauf" aria-label="Permalink to &quot;Zähler-Reset und Überlauf&quot;">​</a></h1><p><a id="device-reset-detected-mean-reset"></a></p><h2 id="was-bedeutet-device-reset-detected-und-wie-funktioniert-die-reset-erkennung" tabindex="-1">Was bedeutet &quot;Device reset detected&quot; und wie funktioniert die Reset-Erkennung? <a class="header-anchor" href="#was-bedeutet-device-reset-detected-und-wie-funktioniert-die-reset-erkennung" aria-label="Permalink to &quot;Was bedeutet &quot;Device reset detected&quot; und wie funktioniert die Reset-Erkennung?&quot;">​</a></h2><p>Es ist eine Warnung, kein Fehler. Der Zählerstand der Quelle ist deutlich gefallen, etwa nach einem Neustart, Stromausfall, Überlauf oder Zählertausch, und SourceAnalytix zählt auf den bisherigen Gesamtstand weiter. Es entstehen keine negativen Werte.</p><h3 id="die-begriffe" tabindex="-1">Die Begriffe <a class="header-anchor" href="#die-begriffe" aria-label="Permalink to &quot;Die Begriffe&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Zieleinheit</td><td>Einheit der Preisdefinition, in der alles gerechnet wird</td></tr><tr><td>Gerätewert</td><td>Wert des Quell-Datenpunkts in der Zieleinheit; kann zurückfallen</td></tr><tr><td>Gesamtstand</td><td><code>cumulativeReading</code>, der eigene Zählerstand von SourceAnalytix; fällt mit Reset-Erkennung nie</td></tr><tr><td>Offset</td><td>Gesamtstand = Gerätewert + Offset; steht bei der Quelle unter „Für Experten“ als <code>valueAtDeviceReset</code></td></tr><tr><td>Startwert</td><td>Gesamtstand zu Beginn einer Periode; Verbrauch = Gesamtstand − Startwert</td></tr><tr><td>Schwelle</td><td>größter Rückgang, der noch als Messschwankung gilt, Standard 1</td></tr></tbody></table><h3 id="ablauf" tabindex="-1">Ablauf <a class="header-anchor" href="#ablauf" aria-label="Permalink to &quot;Ablauf&quot;">​</a></h3><ol><li><strong>Gleich oder höher:</strong> Der Wert wird übernommen.</li><li><strong>Niedriger bis zur Schwelle:</strong> Messschwankung, der Wert wird ignoriert.</li><li><strong>Deutlich niedriger:</strong> möglicher Reset. SourceAnalytix behält den Gesamtstand und wartet auf den nächsten Wert („Waiting for another reading …“).</li><li><strong>Der nächste Wert entscheidet:</strong> Liegt er wieder nahe am alten Stand, war es ein Ausreißer („Rejected a possible device reset“). Bleibt er unten, ist der Reset bestätigt („Device reset detected …“), und der Offset wird neu gesetzt. Kommt der alte Stand nach einem bestätigten Reset in einem Schritt zurück, nimmt SourceAnalytix den Reset zurück („Rolled back the device reset …“).</li></ol><p>Beispiel mit Schwelle 1 kWh, Zähler bei 1.000 kWh, nach Stromausfall bei 0:</p><table tabindex="0"><thead><tr><th>Gerätewert</th><th>Offset</th><th>Gesamtstand</th></tr></thead><tbody><tr><td>1.000 kWh</td><td>0</td><td>1.000 kWh</td></tr><tr><td>0 kWh</td><td>0</td><td>1.000 kWh (wartet)</td></tr><tr><td>0,4 kWh</td><td>1.000</td><td>1.000,4 kWh</td></tr></tbody></table><p>Es fehlt nur, was das Gerät zwischen seinem letzten Wert vor dem Reset und dem ersten danach gezählt hat. War SourceAnalytix während des Resets gestoppt, erkennt es ihn beim ersten Wert nach dem Start, solange das Gerät den alten Stand noch nicht überholt hat. Leistungsquellen haben keine Reset-Erkennung.</p><p>Ohne Reset-Erkennung übernimmt SourceAnalytix jeden Rückgang, Gesamtstand und Perioden fallen mit. Das ist nur für Quellen gedacht, die bewusst fallen dürfen.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Schwelle und Abschalten</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Zähler startet nach Stromausfall bei 0</a></p><p><a id="counter-reset-0-daily-happens"></a></p><h2 id="zahler-der-taglich-auf-0-zuruckgesetzt-wird-–-was-passiert-intern" tabindex="-1">Zähler, der täglich auf 0 zurückgesetzt wird – was passiert intern? <a class="header-anchor" href="#zahler-der-taglich-auf-0-zuruckgesetzt-wird-–-was-passiert-intern" aria-label="Permalink to &quot;Zähler, der täglich auf 0 zurückgesetzt wird – was passiert intern?&quot;">​</a></h2><p>Mit Reset-Erkennung ist der nächtliche Sprung auf 0 ein gewöhnlicher Reset: Der Gesamtstand läuft weiter, pro Nacht fehlt nur ein kleiner Rest. Ohne Reset-Erkennung fällt der Gesamtstand, und der Verbrauch des Vortags wird wieder abgezogen.</p><p>Beispiel mit Schwelle 0,1 kWh, Tageszähler am Abend bei 4,2 kWh:</p><table tabindex="0"><thead><tr><th>Zeit</th><th>Gerätewert</th><th>Gesamtstand</th><th>Was passiert</th></tr></thead><tbody><tr><td>23:58</td><td>4,2 kWh</td><td>1.004,2 kWh</td><td>–</td></tr><tr><td>0:00</td><td>–</td><td>1.004,2 kWh</td><td>Periodenwechsel, neuer Tag beginnt bei 0</td></tr><tr><td>0:01</td><td>0 kWh</td><td>1.004,2 kWh</td><td>wartet</td></tr><tr><td>0:10</td><td>0,05 kWh</td><td>1.004,25 kWh</td><td>Reset bestätigt, heute 0,05 kWh</td></tr></tbody></table><p>Ob das Gerät kurz vor oder nach Mitternacht zurückspringt, spielt keine Rolle. Ist die Schwelle größer als der Tagesverbrauch, gilt der Sprung als Schwankung, und der Anfang des neuen Tages fehlt. Der Assistent markiert Tageszähler mit „Tageszähler“; nimm, wenn möglich, den Gesamtzähler des Geräts.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Mein Zähler startet täglich bei 0</a> · <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler oder Leistung?</a></p>',20)])])}const f=t(d,[["render",i]]);export{g as __pageData,f as default};
